import { parse, expandAllEvents, serialize, buildCalendar } from './ical/index.js';

let allEvents       = [];
let currentView     = 'list';
let parsedCalendar  = null;

// Format date for display
function formatDate(date) {
  const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
  return date.toLocaleDateString('en-US', options);
}

// Format time for display
function formatTime(date) {
  return date.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
}

// Clean HTML from description
// (ICS text unescaping is already handled by the library's parseText())
function cleanDescription(desc) {
  if (!desc) return '';

  desc = desc.replace(/<br\s*\/?>/gi, '\n');
  desc = desc.replace(/<a\s+href="([^"]+)"[^>]*>([^<]+)<\/a>/gi, '<a href="$1" target="_blank">$2</a>');
  desc = desc.replace(/<[^>]+>/g, '');

  const textarea = document.createElement('textarea');
  textarea.innerHTML = desc;
  desc = textarea.value;

  desc = desc.replace(/(?<!href=")(https?:\/\/[^\s<]+)/g, '<a href="$1" target="_blank">$1</a>');

  return desc;
}

// Group events by month
function groupEventsByMonth(events) {
  const grouped = {};

  events.forEach(event => {
    const monthKey = `${event.start.getFullYear()}-${String(event.start.getMonth() + 1).padStart(2, '0')}`;
    const monthName = event.start.toLocaleDateString('en-US', { year: 'numeric', month: 'long' });

    if (!grouped[monthKey]) {
      grouped[monthKey] = { name: monthName, events: [] };
    }

    grouped[monthKey].events.push(event);
  });

  return grouped;
}

// Store events data for button access
const eventDataMap = new Map();

// Display events
function displayEvents(events) {
  const container = document.getElementById('events-list-container');

  if (events.length === 0) {
    container.innerHTML = '<div class="no-events-message">No events found for the selected date range.</div>';
    return;
  }

  eventDataMap.clear();
  events.sort((a, b) => a.start - b.start);

  const groupedEvents = groupEventsByMonth(events);
  let html = '<div class="events-container">';

  Object.keys(groupedEvents).sort().forEach(monthKey => {
    const month = groupedEvents[monthKey];

    html += `<div class="month-section">`;
    html += `<div class="month-header">${month.name}</div>`;

    month.events.forEach((event, index) => {
      const dateStr = formatDate(event.start);
      const timeStr = event.isAllDay ? 'All Day' : `${formatTime(event.start)} - ${formatTime(event.end)}`;
      const description = cleanDescription(event.description);
      const location = event.location;

      const eventId = `event-${event.start.getTime()}-${index}`;

      eventDataMap.set(eventId, {
        title:       event.title,
        start:       event.start,
        end:         event.end,
        description: event.description,
        location:    event.location,
        isAllDay:    event.isAllDay,
        vevent:      event.vevent,
      });

      html += `
        <div class="event-card" id="${eventId}">
          <div class="event-date">
            <span class="event-date-text">${dateStr}</span>
            <button class="share-button" onclick="addToCalendar('${eventId}')" title="Add to your calendar">
              📅 Add
            </button>
            <button class="share-button" onclick="copyEventLink('${eventId}')" title="Copy link to clipboard">
              📋 Copy
            </button>
            <button class="share-button" onclick="shareEvent('${eventId}')" title="Share this event">
              🔗 Share
            </button>
          </div>
          <div class="event-time">${timeStr}</div>
          <div class="event-title">${event.title}</div>
          ${location ? `<div class="event-location">📍 ${location}</div>` : ''}
          ${description ? `<div class="event-description">${description}</div>` : ''}
        </div>
      `;
    });

    html += `</div>`;
  });

  html += '</div>';
  container.innerHTML = html;
}

// Filter events by date range
function filterEvents(startDate, endDate) {
  return allEvents.filter(event => event.start >= startDate && event.start <= endDate);
}

// Filter: This Month
function filterThisMonth() {
  const now = new Date();
  const start = new Date(now.getFullYear(), now.getMonth(), 1);
  const end = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59);
  displayEvents(filterEvents(start, end));
}

// Filter: Next Month
function filterNextMonth() {
  const now = new Date();
  const start = new Date(now.getFullYear(), now.getMonth() + 1, 1);
  const end = new Date(now.getFullYear(), now.getMonth() + 2, 0, 23, 59, 59);
  displayEvents(filterEvents(start, end));
}

// Filter: Custom Range
function filterCustomRange() {
  const startInput = document.getElementById('start-date').value;
  const endInput = document.getElementById('end-date').value;

  if (!startInput || !endInput) {
    alert('Please select both start and end dates');
    return;
  }

  const [sy, sm, sd] = startInput.split('-').map(Number);
  const [ey, em, ed] = endInput.split('-').map(Number);

  const start = new Date(sy, sm - 1, sd, 0, 0, 0, 0);
  const end   = new Date(ey, em - 1, ed, 23, 59, 59, 999);

  if (start > end) {
    alert('Start date must be before end date');
    return;
  }

  displayEvents(filterEvents(start, end));
}

// Clear filter and show all upcoming events
function clearFilter() {
  const now = new Date();
  displayEvents(allEvents.filter(event => event.start > now));
}

// Toggle between list and iframe view
function toggleCalendarView() {
  const listContainer  = document.getElementById('events-list-container');
  const iframeContainer = document.getElementById('calendar-iframe-container');
  const toggleBtn      = document.getElementById('toggle-view-btn');
  const filterControls = document.getElementById('filter-controls');
  const searchBox      = document.getElementById('search-input').parentElement;

  if (currentView === 'list') {
    listContainer.style.display  = 'none';
    iframeContainer.style.display = 'block';
    filterControls.style.display = 'none';
    searchBox.style.display      = 'none';
    toggleBtn.textContent        = 'Switch to List View';
    currentView = 'iframe';
  } else {
    listContainer.style.display  = 'block';
    iframeContainer.style.display = 'none';
    filterControls.style.display = 'block';
    searchBox.style.display      = 'block';
    toggleBtn.textContent        = 'Switch to Calendar View';
    currentView = 'list';
  }
}

// Get search parameter from URL
function getSearchParameter() {
  const params = new URLSearchParams(window.location.search);
  return params.get('search') ? params.get('search').toLowerCase().trim() : null;
}

// Filter events by search term
function filterEventsBySearch(events, searchTerm) {
  if (!searchTerm) return events;
  return events.filter(event => {
    const title       = (event.title       || '').toLowerCase();
    const description = (event.description || '').toLowerCase();
    return title.includes(searchTerm) || description.includes(searchTerm);
  });
}

// Handle search input changes
function setupSearchInput() {
  const searchInput = document.getElementById('search-input');
  if (!searchInput) return;

  const searchTerm = getSearchParameter();
  if (searchTerm) searchInput.value = searchTerm;

  let searchDebounce = null;
  searchInput.addEventListener('input', (e) => {
    clearTimeout(searchDebounce);
    searchDebounce = setTimeout(() => {
      const term = e.target.value.toLowerCase().trim();

      if (term) {
        window.history.pushState({ search: term }, '', `${window.location.pathname}?search=${encodeURIComponent(term)}`);
        const filtered = filterEventsBySearch(allEvents, term);
        displayEvents(filtered);
        console.log(`Searching for: "${term}" - Found ${filtered.length} matching events`);
      } else {
        window.history.pushState({}, '', window.location.pathname);
        clearFilter();
      }
    }, 500);
  });
}

// Convert a library expanded-event record to a plain display object
function toDisplayEvent({ start, vevent }, tzReg) {
  const durationMs  = vevent.duration(tzReg) ?? 0;
  const end         = new Date(start.getTime() + durationMs);
  const dtstartProp = vevent.dtstartProp;
  const isAllDay    = dtstartProp ? !dtstartProp.value.includes('T') : false;

  return {
    title:       vevent.summary     || 'Untitled Event',
    start,
    end,
    description: vevent.description || '',
    location:    vevent.location    || '',
    isAllDay,
    vevent,  // keep reference so addToCalendar can build a series ICS
  };
}

// Fetch and parse calendar using the ical library
async function loadCalendar() {
  const container = document.getElementById('events-list-container');

  try {
    const response = await fetch('/api/calendar');
    if (!response.ok) throw new Error('Failed to fetch calendar');

    const icsText = await response.text();
    const { calendar, tzRegistry } = parse(icsText);
    parsedCalendar = calendar;

    // Expand over a wide window so search can reach all events
    const windowStart = new Date(2000, 0, 1);
    const windowEnd   = new Date(Date.now() + 2 * 365 * 24 * 60 * 60 * 1000);

    const expanded = expandAllEvents(calendar.events, windowStart, windowEnd, tzRegistry);
    allEvents = expanded.map(item => toDisplayEvent(item, tzRegistry));

    const now     = new Date();
    const endDate = new Date(now.getFullYear(), now.getMonth() + 3, 0, 23, 59, 59, 999);

    const searchTerm = getSearchParameter();
    let filtered;

    if (searchTerm) {
      filtered = filterEventsBySearch(allEvents, searchTerm);
      console.log(`Searching for: "${searchTerm}" - Found ${filtered.length} matching events`);
    } else {
      filtered = allEvents.filter(event => event.start > now && event.start <= endDate);
      console.log(`Showing ${filtered.length} events from ${now.toLocaleDateString()} to ${endDate.toLocaleDateString()}`);
    }

    displayEvents(filtered);

  } catch (error) {
    console.error('Error loading calendar:', error);
    container.innerHTML = `
      <div class="error-message">
        <strong>Unable to load calendar events right now.</strong><br>
        Please try refreshing the page or switch to Calendar View to see events.
      </div>
    `;
  }
}

// Show notification toast
function showNotification(message) {
  const existing = document.querySelector('.copy-notification');
  if (existing) existing.remove();

  const notification = document.createElement('div');
  notification.className = 'copy-notification';
  notification.textContent = message;
  document.body.appendChild(notification);

  setTimeout(() => notification.classList.add('show'), 10);
  setTimeout(() => {
    notification.classList.remove('show');
    setTimeout(() => notification.remove(), 300);
  }, 3000);
}

// Format date for ICS file
function formatICSDate(date, isAllDay = false) {
  const year    = date.getFullYear();
  const month   = String(date.getMonth() + 1).padStart(2, '0');
  const day     = String(date.getDate()).padStart(2, '0');

  if (isAllDay) return `${year}${month}${day}`;

  const hours   = String(date.getHours()).padStart(2, '0');
  const minutes = String(date.getMinutes()).padStart(2, '0');
  const seconds = String(date.getSeconds()).padStart(2, '0');
  return `${year}${month}${day}T${hours}${minutes}${seconds}`;
}

// Add to calendar - downloads a single-occurrence ICS, or the full series for recurring events
function addToCalendar(eventId) {
  const event = eventDataMap.get(eventId);
  if (!event) return;

  // For recurring events, serialize the full series using the library
  if (event.vevent?.isRecurring && parsedCalendar) {
    const uid = event.vevent.uid;

    // Collect master event + any RECURRENCE-ID overrides sharing the same UID
    const seriesRaw = parsedCalendar.events
      .filter(e => e.uid === uid)
      .map(e => e._raw);

    // Include the VTIMEZONE block if DTSTART has a TZID
    const tzid = event.vevent.dtstartProp?.param('TZID');
    const tzRaw = tzid
      ? parsedCalendar.timezones.filter(tz => tz.tzid === tzid).map(tz => tz._raw)
      : [];

    const calRaw    = buildCalendar([...tzRaw, ...seriesRaw], { prodid: '-//Kzoo Makers//Calendar//EN' });
    const icsContent = serialize(calRaw);

    const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
    const link = document.createElement('a');
    link.href     = URL.createObjectURL(blob);
    link.download = `${event.title.replace(/[^a-z0-9]/gi, '_')}_series.ics`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(link.href);

    showNotification('📅 Calendar series downloaded!');
    return;
  }

  // Single (non-recurring) event — build a minimal ICS by hand
  const startDate = formatICSDate(event.start, event.isAllDay);
  const endDate   = formatICSDate(event.end,   event.isAllDay);
  const now       = formatICSDate(new Date());

  const escapeICS = str =>
    str.replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\n/g, '\\n');

  const icsContent = [
    'BEGIN:VCALENDAR',
    'VERSION:2.0',
    'PRODID:-//Kzoo Makers//Calendar//EN',
    'BEGIN:VEVENT',
    `UID:${eventId}@kzoomakers.org`,
    `DTSTAMP:${now}`,
    `DTSTART:${startDate}`,
    `DTEND:${endDate}`,
    `SUMMARY:${escapeICS(event.title)}`,
    event.location    ? `LOCATION:${escapeICS(event.location)}`       : '',
    event.description ? `DESCRIPTION:${escapeICS(event.description)}` : '',
    'END:VEVENT',
    'END:VCALENDAR',
  ].filter(Boolean).join('\r\n');

  const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
  const link = document.createElement('a');
  link.href     = URL.createObjectURL(blob);
  link.download = `${event.title.replace(/[^a-z0-9]/gi, '_')}.ics`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(link.href);

  showNotification('📅 Calendar file downloaded!');
}

// Copy event link directly to clipboard
function copyEventLink(eventId) {
  copyToClipboard(`${window.location.origin}${window.location.pathname}#${eventId}`);
}

// Share event function
function shareEvent(eventId) {
  const event = eventDataMap.get(eventId);
  const url   = `${window.location.origin}${window.location.pathname}#${eventId}`;

  if (!event) { copyToClipboard(url); return; }

  const shareText = `Check out the Kzoo Makers meeting "${event.title}" on ${formatDate(event.start)} at ${url}`;

  if (navigator.share) {
    navigator.share({ title: `Kzoo Makers: ${event.title}`, text: shareText, url })
      .catch(err => { if (err.name !== 'AbortError') copyToClipboard(url); });
  } else {
    copyToClipboard(url);
  }
}

// Copy URL to clipboard
function copyToClipboard(text) {
  if (navigator.clipboard?.writeText) {
    navigator.clipboard.writeText(text)
      .then(() => showNotification('🔗 Link copied to clipboard!'))
      .catch(() => fallbackCopyToClipboard(text));
  } else {
    fallbackCopyToClipboard(text);
  }
}

// Fallback copy for older browsers
function fallbackCopyToClipboard(text) {
  const textArea = document.createElement('textarea');
  textArea.value = text;
  textArea.style.cssText = 'position:fixed;left:-999999px';
  document.body.appendChild(textArea);
  textArea.focus();
  textArea.select();
  try {
    document.execCommand('copy');
    showNotification('🔗 Link copied to clipboard!');
  } catch {
    showNotification('❌ Unable to copy link');
  }
  document.body.removeChild(textArea);
}

// Scroll to event if hash is present in URL
function scrollToEventIfNeeded() {
  if (!window.location.hash) return;
  const element = document.getElementById(window.location.hash.substring(1));
  if (!element) return;
  setTimeout(() => {
    element.scrollIntoView({ behavior: 'smooth', block: 'center' });
    element.style.backgroundColor = '#fff3cd';
    setTimeout(() => {
      element.style.transition = 'background-color 1s ease';
      element.style.backgroundColor = 'white';
    }, 1000);
  }, 500);
}

// Show purge notification
function showPurgeNotification(message, isError = false) {
  const existing = document.querySelector('.purge-notification');
  if (existing) existing.remove();

  const notification = document.createElement('div');
  notification.className = 'purge-notification';
  if (isError) notification.classList.add('error');
  notification.textContent = message;
  document.body.appendChild(notification);

  setTimeout(() => notification.classList.add('show'), 10);
  setTimeout(() => {
    notification.classList.remove('show');
    setTimeout(() => notification.remove(), 300);
  }, 5000);
}

// Expose functions required by inline onclick handlers to global scope
window.toggleCalendarView = toggleCalendarView;
window.filterThisMonth    = filterThisMonth;
window.filterNextMonth    = filterNextMonth;
window.filterCustomRange  = filterCustomRange;
window.clearFilter        = clearFilter;
window.addToCalendar      = addToCalendar;
window.copyEventLink      = copyEventLink;
window.shareEvent         = shareEvent;

// Load calendar when page loads
document.addEventListener('DOMContentLoaded', () => {
  loadCalendar().then(() => {
    scrollToEventIfNeeded();
    setupSearchInput();
  });

  // Purge button functionality
  const purgeButton = document.getElementById('purge-button');
  let isClicked = false;

  purgeButton.addEventListener('mouseenter', () => {
    if (!isClicked) purgeButton.classList.add('show-hover-image');
  });

  purgeButton.addEventListener('mouseleave', () => {
    if (!isClicked) purgeButton.classList.remove('show-hover-image');
  });

  purgeButton.addEventListener('click', async () => {
    isClicked = true;
    purgeButton.classList.remove('show-hover-image');
    purgeButton.classList.add('show-click-image');

    await new Promise(resolve => setTimeout(resolve, 1000));

    purgeButton.classList.remove('show-click-image');
    isClicked = false;

    try {
      const response = await fetch('/api/calendar?purge');
      if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
      showPurgeNotification(await response.text());
    } catch (error) {
      showPurgeNotification(`Failed to issue request: ${error.message}`, true);
    }
  });
});

