  .calendar-controls, #calendar-iframe-container,
  .purge-button, [style*="purge"] {
    display: none !important;
  }

  /* Remove section padding/margins that waste paper space */
  #calendar.section {
    padding: 0 !important;
    margin: 0 !important;
  }

  /* Print header above the event list */
  #events-list-container::before {
    content: "Kzoo Makers — Upcoming Events";
    display: block;
    font-size: 22pt;
    font-weight: bold;
    text-align: center;
    margin-bottom: 16pt;
  }

  /* Keep cards readable but compact */
  .event-card {
    box-shadow: none !important;
    border: 1px solid #ccc !important;
    break-inside: avoid;
    page-break-inside: avoid;
    margin-bottom: 12pt !important;
  }

  .event-card:hover {
    transform: none !important;
  }

  /* Hide per-card action buttons */
  .share-button {
    display: none !important;
  }

  /* Month headers */
  .month-header {
    background-color: #47424C !important;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
    break-after: avoid;
    page-break-after: avoid;
  }

  /* Avoid orphaned month headers */
  .month-section {
    break-inside: avoid;
    page-break-inside: avoid;
  }
}
